effect.shader:
vec2 getResolution(){
  vec2 s = getTexSize(inputImg.size);
  if (s.x <= 0.0 || s.y <= 0.0) s = vec2(1920.0, 1080.0);
  return s;
}
vec2 hash2(float n){ return fract(sin(vec2(n, n + 1.0)) * 43758.5453); }
float intersectSphere(vec3 ro, vec3 rd, vec3 center, float radius){
  vec3 oc = ro - center;
  float b = dot(oc, rd);
  float c = dot(oc, oc) - radius * radius;
  float h = b*b - c;
  if (h < 0.0) return -1.0;
  return -b - sqrt(h);
}
void main(){
  vec2 res = getResolution();
  vec2 fragCoord = acScreenNorm * res;
  vec2 uv = acScreenNorm;
  vec2 p = (fragCoord - 0.5 * res) / res.y;
  vec3 ro = vec3(0.0, 0.0, -2.0);
  vec3 rd = normalize(vec3(p, fov));
  vec3 lightPos = normalize(vec3(lightX, lightY, lightZ));
  vec3 col = texture2DCv(inputImg.texture, uv).rgb;
  float minT = 10000.0;
  vec3 hitCenter = vec3(0.0);
  int maxBalls = int(ballCount);
  float aspect = res.x / res.y;
  for(int i=0;i<400;i++){
    if (i >= maxBalls) break;
    vec2 rnd = hash2(float(i) * 56.7 + randSeed);
    float t_anim = progress * 20.0 + (float(i) * 12.0);
    vec3 center = vec3(0.0);
    center.x = sin(t_anim + rnd.x * 6.2831853) * 0.8 * aspect * spread;
    center.y = cos(t_anim * 0.9 + rnd.y * 6.2831853) * 0.4 * spread;
    center.z = sin(t_anim * 0.5) * zSpread;
    center += vec3(posX, posY, posZ);
    float rVar = 1.0;
    if (randomSize){ rVar = 1.0 + (rnd.x * 2.0 - 1.0) * sizeVar; }
    float rBall = clamp(ballRadius * rVar, 0.001, 10.0);
    float t = intersectSphere(ro, rd, center, rBall);
    if (t > 0.0 && t < minT){ minT = t; hitCenter = center; }
  }
  if (minT < 10000.0){
    vec3 pos = ro + rd * minT;
    vec3 normal = normalize(pos - hitCenter);
    vec3 viewDir = -rd;
    float cosTheta = clamp(dot(normal, viewDir), 0.0, 1.0);
    float fresnel = pow(1.0 - cosTheta, 4.0);
    float reflStrength = (0.1 + 0.9 * fresnel) * reflectMix;
    vec3 refrVec = refract(rd, normal, 1.0 / ior);
    vec2 refrUV = uv + refrVec.xy * refractScale;
    vec3 glassColor = texture2DCv(inputImg.texture, refrUV).rgb;
    vec3 absorb = ballColor.rgb * (0.5 + 0.5 * cosTheta);
    glassColor *= absorb * 1.5;
    vec3 reflVec = reflect(rd, normal);
    vec2 reflUV = uv + reflVec.xy * reflectScale;
    vec3 reflColor = texture2DCv(inputImg.texture, reflUV).rgb;
    vec3 halfVec = normalize(lightPos + viewDir);
    float spec = pow(max(dot(normal, halfVec), 0.0), shininess);
    vec3 sphereCol = mix(glassColor, reflColor, reflStrength);
    sphereCol += vec3(1.0) * spec;
    sphereCol += vec3(1.0, 0.2, 0.2) * fresnel * 0.3;
    col = sphereCol;
  }
  gl_FragColor = vec4(col, 1.0);
}
